import { useState } from "react";
import { useSelector } from "react-redux";
import { selectCartTotal } from "../../store/cart/cart.selector";
import { selectCurrentUser } from "../../store/user/user.selector";
import { CardElement, useStripe, useElements } from "@stripe/react-stripe-js";
import Button, { BUTTON_TYPE_CLASSES } from "../button/button.component";
import { PaymentFormContainer, FormContainer, CardContainer } from "./payment-form.styles";

const PaymentForm = () => {
    const stripe = useStripe();
    const elements = useElements();
    const cartTotal = useSelector(selectCartTotal);
    const currentUser = useSelector(selectCurrentUser);
    const [isProcessingPayment, setIsProcessingPayment] = useState(false);

    const paymentHandler = async (e) => {
        e.preventDefault();

        if (!stripe || !elements) {
            return;
        }

        setIsProcessingPayment(true);

        const response = await fetch("/.netlify/functions/create-payment-intent", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({ amount: cartTotal * 100 }), // Stripe expects the amount in cents
        }).then((res) => res.json());

        if (!response.ok) {
            console.error("Error creating Payment Intent:", response.status, response.statusText);
            return;
        }

        console.log("Payment Intent response:", response);

        const { client_secret } = response.paymentIntent;

        const paymentResult = await stripe.confirmCardPayment(client_secret, {
            payment_method: {
                card: elements.getElement(CardElement),
                billing_details: {
                    name: currentUser ? currentUser : "Guest"
                },
            },
        });

        setIsProcessingPayment(false);

        if (paymentResult.error) {
            console.error("Payment error:", paymentResult.error.message);
        } else if (paymentResult.paymentIntent.status === "succeeded") {
            console.log("Payment successful!");
        } else {
            console.log("Payment status:", paymentResult.paymentIntent.status);
        }
    };

    return (
        <PaymentFormContainer>
            <FormContainer onSubmit={paymentHandler}>
                <h2>Credit Card Payment:</h2>
                <CardContainer>
                    <CardElement />
                </CardContainer>
                <Button
                    isLoading={isProcessingPayment}
                    buttonType={BUTTON_TYPE_CLASSES.inverted}
                >
                    Pay Now
                </Button>
            </FormContainer>
        </PaymentFormContainer>
    );
}

export default PaymentForm;
